contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to deposit first, then invokes withdrawAll and checks the invariant
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // record contract balance before any interactions
        uint cBalBefore = address(c).balance;

        // make a deposit to create credit for this test contract in c
        c.deposit{value: depositAmount}();

        // read the credit for this contract (via the public mapping getter)
        uint creditBefore = c.credit(address(this));

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-states visible externally
        uint creditAfter = c.credit(address(this));
        uint cBalAfter = address(c).balance;

        // General rule: if withdrawAll did not revert, then credit became zero and the contract's balance decreased by exactly the previous credit amount; if it reverted, we cannot assume changes, so allow any state
        assert(reverted || (creditAfter == 0 && cBalBefore - cBalAfter == creditBefore));
    }

    // receive to accept Ether from C during withdrawAll
    receive() external payable {}
}

