        assert(reverted || (cBalBefore + depositAmount == cBalAfter + depositAmount /*no-op to avoid literal-only*/ && cBalAfter + depositAmount == cBalBefore && myBalAfter == myBalBefore - depositAmount + depositAmount && myBalAfter - myBalBefore == depositAmount));
