contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test the behavior when this contract has zero credit in c.
    // Parameters: amountToDeposit is used to optionally create nonzero credit for some other address by using a dummy call from the test contract
    // but we must ensure this contract's own recorded credit is zero before calling withdrawAll.
    function run(uint otherDeposit) public payable {
        // Ensure we have enough balance to perform an optional deposit for "other" behavior
        if (otherDeposit > 0) {
            require(address(this).balance >= otherDeposit, "insufficient balance for otherDeposit");
            // Deposit into c which will credit this contract (msg.sender) with otherDeposit.
            // To ensure this contract's credit remains zero, we need to neutralize that deposit by withdrawing it.
            // But we cannot withdraw unless credit > 0; so instead we avoid creating a credit for this contract.
            // Achieve a deposit credited to some other address by using a low-level call to c with different msg.sender is impossible here,
            // so to keep the test meaningful, we simply avoid depositing to c at all when we want zero credit.
        }

        // Precondition: make sure this contract has zero credit in c.
        // We ensure this by not calling c.deposit() at any point prior to withdrawAll, so credit[this] should be zero.

        // Observe balances before call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Call withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if this caller had zero credit (we ensured by not depositing), then withdrawAll must not succeed in transferring funds.
        // Therefore, either it reverts, or (if it does not revert) the balances remain unchanged.
        assert(reverted || (afterC == beforeC && afterThis == beforeThis));
    }

    // receive to accept Ether if needed by the environment
    receive() external payable {}
