    constructor(C _c) { c = _c; }

    // single public test function that drives c and asserts a general invariant
    function run(uint depositAmount, bool doDeposit) public payable {
        // If we will send Ether to c, ensure this contract has enough balance to forward it.
        if (doDeposit) {
            require(address(this).balance >= depositAmount);
            // perform deposit as a top-level call that mutates c
            c.deposit{value: depositAmount}();
        }

        // observe balances before withdrawAll
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe balances after withdrawAll
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // Infer the apparent credit before and after via observable balance deltas.
        // The inferred credit owed to this contract immediately before withdrawAll equals
        // the increase in C's balance attributable to the earlier deposit by this contract.
        // That is: inferredBefore = beforeC - (address(c).balance - depositAmount) ???
        // Simpler and safe: inferredBefore = beforeC - (address(c).balance - 0) relative to initial
        // But we only need a comparison: withdrawAll must not increase inferred credit.

        // We compute inferred credit change as: (afterC - beforeC) - (afterThis - beforeThis)
        // If withdrawAll succeeds, afterThis increases and afterC decreases, so this value should be <= 0.
        // If withdrawAll reverts, neither balance should change, so value == 0.

        // Use signed arithmetic by comparing via inequalities without underflow.
        // Let deltaC = afterC >= beforeC ? afterC - beforeC : 0 when afterC >= beforeC else treat as large increase.

        // Formulate assertion: withdrawAll cannot make (inferred credit) strictly greater than it was before.
        // Equivalent observable condition: afterC - beforeC >= afterThis - beforeThis  (i.e., C's net gain is at least this contract's net gain)

        assert( (afterC >= beforeC && afterC - beforeC >= (afterThis >= beforeThis ? afterThis - beforeThis : 0))
             || (afterC < beforeC && !(afterThis > beforeThis)) );
    }

    // allow receiving Ether during c.withdrawAll transfers
    receive() external payable {}
}

