    constructor(C _c) { c = _c; }

    // single public test function: try an optional deposit amount, then call withdrawAll and check the invariant
    function run(uint depositAmount, bool doDeposit) public payable {
        require(true);

        // If we will deposit, ensure this contract has enough balance to forward the funds
        if (doDeposit) {
            require(address(this).balance >= depositAmount);
            // depositAmount may be zero; deposit must be a top-level call
            c.deposit{value: depositAmount}();
        }

        // observe c's balance before calling withdrawAll
        uint cBalanceBefore = address(c).balance;
        // observe this contract's balance before
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        // call withdrawAll and catch revert
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe this contract's balance after
        uint thisBalanceAfter = address(this).balance;

        // amount received (if call reverted, no state change in C should have occurred, so received is 0)
        uint received = thisBalanceAfter >= thisBalanceBefore ? thisBalanceAfter - thisBalanceBefore : 0;

        // General rule: the Ether received by this contract from withdrawAll cannot exceed the prior balance of c
        // If withdrawAll reverted, received must be 0; otherwise received <= cBalanceBefore.
        assert((reverted && received == 0) || (!reverted && received <= cBalanceBefore));
    }

    // allow receiving Ether sent by C during withdrawAll
    receive() external payable {}
}

