        }

        // observe balances after
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        // compute observed changes without underflow: use comparisons
        uint cDecrease = cBalanceBefore >= cBalanceAfter ? cBalanceBefore - cBalanceAfter : 0;
        uint thisIncrease = thisBalanceAfter >= thisBalanceBefore ? thisBalanceAfter - thisBalanceBefore : 0;

