contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking two deposit amounts and a flag whether to call withdraw
    function run(uint depositAmount, uint extraDeposit, bool doWithdraw) public payable {
        require(true);

        // ensure we have enough balance locally if we will send Ether
        if (depositAmount > 0 || extraDeposit > 0) {
            require(address(this).balance >= depositAmount + extraDeposit);
        }

        // Observe initial balances
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Optionally perform two deposits (each is a top-level call)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }
        if (extraDeposit > 0) {
            c.deposit{value: extraDeposit}();
        }

        // Observe balances after deposits (this gives an observable notion of recorded credit)
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Inferred credit for this contract (as observed increase in c's balance relative to this contract's decrease)
        // We avoid subtraction that could underflow by using comparisons in the final assert; compute as deltas where safe
        uint deltaC_postDeposit = afterDepositC >= beforeC ? afterDepositC - beforeC : 0;
        uint deltaThis_postDeposit = beforeThis >= afterDepositThis ? beforeThis - afterDepositThis : 0;

        // Now call withdrawAll optionally, capturing whether it reverted
        bool reverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false; // no withdraw attempted
        }

        // Observe balances after withdraw attempt
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // Compute observed deltas safely
        uint deltaC_final = finalC >= afterDepositC ? finalC - afterDepositC : afterDepositC - finalC;
        uint deltaThis_final = finalThis >= afterDepositThis ? finalThis - afterDepositThis : afterDepositThis - finalThis;

        // General invariant: withdrawAll cannot increase the caller's recorded credit inferred from balances.
        // Formally: the inferred credit (increase of C's balance vs decrease of this contract) after the withdraw call
        // is not greater than the inferred credit immediately after deposits. We express this as:
        // If inferred_credit_after_withdraw = max(0, finalC - finalThis - (beforeC - beforeThis)) and
        // inferred_credit_after_deposit = max(0, afterDepositC - afterDepositThis - (beforeC - beforeThis))
        // then inferred_credit_after_withdraw <= inferred_credit_after_deposit.
        // We avoid signed arithmetic by rearranging into observable comparisons using only non-underflowing ops.

        // Implement equivalent comparison without underflow by comparing the differences of deltas:
        // (finalC - finalThis) <= (afterDepositC - afterDepositThis)  -> ensures recorded credit didn't grow
        // rewrite as finalC + afterDepositThis <= afterDepositC + finalThis to avoid subtraction underflow
        assert(finalC + afterDepositThis <= afterDepositC + finalThis);
    }

    receive() external payable { }
}

