contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit an amount (possibly zero) then call withdrawAll and check relation
    function run(uint depositAmount) public payable {
        // ensure this contract has enough Ether to pay depositAmount
        require(address(this).balance >= depositAmount);

        // read balances before any action
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // perform deposit to C with specified amount
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        } else {
            // still call deposit with zero to exercise path
            c.deposit{value: 0}();
        }

        // read balances after deposit and before withdrawAll
        uint cBalAfterDeposit = address(c).balance;
        uint selfBalAfterDeposit = address(this).balance;

        // call withdrawAll, capture whether it reverted
        bool didRevert;
        try c.withdrawAll() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read balances after withdrawAll
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule: if withdrawAll did not revert then C's balance after equals
        // the balance after deposit minus at most the deposited amount (i.e., it cannot withdraw more than depositAmount)
        // and the decrease in C's balance does not exceed the increase in this contract's balance.
        // Formally: if not reverted then
        //   cBalAfter == cBalAfterDeposit - deltaC  with deltaC <= depositAmount
        //   and selfBalAfter == selfBalAfterDeposit + deltaSelf  with deltaSelf >= deltaC
        // We express this without local subtraction that can underflow in assert by rearranging.

        if (!didRevert) {
            // compute deltas using safe comparisons expressed without underflowing subtraction in assert
            // deltaC = cBalAfterDeposit - cBalAfter  (>= 0)
            // deltaSelf = selfBalAfter - selfBalAfterDeposit (>= 0)

            // assert: cBalAfter <= cBalAfterDeposit (i.e., deltaC >= 0)
            // assert: selfBalAfter >= selfBalAfterDeposit (i.e., deltaSelf >= 0)
            // assert: cBalAfterDeposit - cBalAfter <= depositAmount  (i.e., deltaC <= depositAmount)
            // assert: selfBalAfter - selfBalAfterDeposit >= cBalAfterDeposit - cBalAfter  (i.e., deltaSelf >= deltaC)

            assert(
                cBalAfter <= cBalAfterDeposit
                && selfBalAfter >= selfBalAfterDeposit
                && (cBalAfterDeposit - cBalAfter) <= depositAmount
                && (selfBalAfter - selfBalAfterDeposit) >= (cBalAfterDeposit - cBalAfter)
            );
        } else {
            // If reverted, still reach the assert by asserting a tautology tied to didRevert
            // but must be a general rule — here we assert that if it reverted then either C's balance or this contract's balance did not increase unexpectedly.
            assert(didRevert);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // read balances before any action
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // perform deposit to C with specified amount (top-level state-changing call)
        c.deposit{value: depositAmount}();

        // read balances after deposit and before withdrawAll
        uint cBalAfterDeposit = address(c).balance;
        uint selfBalAfterDeposit = address(this).balance;

        // call withdrawAll, capture whether it reverted (top-level call within try/catch)
        bool didRevert;
        try c.withdrawAll() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // read balances after withdrawAll
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // Single general assertion for all inputs:
        // If withdrawAll did not revert then:
        // 1) C's balance did not increase (cBalAfter <= cBalAfterDeposit)
        // 2) The decrease in C's balance is at most depositAmount: (cBalAfterDeposit - cBalAfter) <= depositAmount
        // 3) This contract's balance did not decrease (selfBalAfter >= selfBalAfterDeposit)
        // 4) This contract's gain is at least C's loss: (selfBalAfter - selfBalAfterDeposit) >= (cBalAfterDeposit - cBalAfter)
        // If withdrawAll reverted, no additional requirement (the formula below becomes true because didRevert is true implies the OR is true).

        assert(
            didRevert || (
                cBalAfter <= cBalAfterDeposit
                && (cBalAfterDeposit - cBalAfter) <= depositAmount
                && selfBalAfter >= selfBalAfterDeposit
                && (selfBalAfter - selfBalAfterDeposit) >= (cBalAfterDeposit - cBalAfter)
            )
        );
    }

    receive() external payable {}
}
